package com.steven.assets.service.srpp.report;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.steven.assets.srpp.*;
import java.time.*;
import java.util.*;

/** Pure semantic guard before publication and before exposing saved packages. No calculation or source I/O. */
public final class SrppReportEnvelopeValidator {
    private SrppReportEnvelopeValidator() {}
    public static final Set<String> MODULES=Set.of("ASSET_RECONCILIATION","ALLOCATION_GAP","FUNDING_CAPACITY","CASH_INCOME","PAYROLL_CASHFLOW","BOND_D130_D195","DIVIDEND_TOPUP","CORE_SELL_GUARD","STRATEGIC_BUY_GATES","GLOBAL_EQUITY_PACE","ROTATION_AND_REGIME_CAPACITY","SHORT_TERM_AND_US_TACTICAL");
    public static JsonNode validate(String raw) {
        try {
            JsonNode n=SrppJcs.parseStrict(raw);keys(n,Set.of("schemaVersion","calculationRunId","status","identity","authorityRevision","sharedCalculationId","inputSnapshot","modules","coverage","executionScope","tradeAuthorization","placesOrders","contentSha256"));
            require(n.path("schemaVersion").isIntegralNumber()&&n.path("schemaVersion").asInt()==1&&"FINAL".equals(text(n,"status"))&&"REPORT_RECOMMENDATION_ONLY".equals(text(n,"executionScope"))&&n.path("tradeAuthorization").isBoolean()&&!n.path("tradeAuthorization").booleanValue()&&n.path("placesOrders").isBoolean()&&!n.path("placesOrders").booleanValue());uuid(n,"calculationRunId");uuid(n,"sharedCalculationId");hash(n,"contentSha256");ObjectNode unhashed=((ObjectNode)n).deepCopy();unhashed.remove("contentSha256");require(SrppJcs.hash(unhashed).equals(n.path("contentSha256").asText()));
            JsonNode identity=n.path("identity");keys(identity,Set.of("ownerUserId","consumer","tradingDate","reportSlot","policyBundleSha256","swaggerSha256"));safePositive(identity.path("ownerUserId"));require(Set.of("Codex","Claude").contains(text(identity,"consumer"))&&Set.of("09:05","12:00").contains(text(identity,"reportSlot")));LocalDate.parse(text(identity,"tradingDate"));hash(identity,"policyBundleSha256");hash(identity,"swaggerSha256");
            JsonNode revision=n.path("authorityRevision");keys(revision,Set.of("serviceBuild","databaseSchema","calculatorVersion","modelInputsSha256","policyManifestSha256","targetAllocationSha256"));for(String k:List.of("serviceBuild","databaseSchema","calculatorVersion"))require(!text(revision,k).isBlank());for(String k:List.of("modelInputsSha256","policyManifestSha256","targetAllocationSha256"))hash(revision,k);
            JsonNode snapshot=n.path("inputSnapshot");keys(snapshot,Set.of("capturedAt","assetGeneratedAt","assetSnapshotId","valuationCaptureId","inputBundleJcs","inputSnapshotSha256","sourceVector"));Instant at=Instant.parse(text(snapshot,"capturedAt"));require(!Instant.parse(text(snapshot,"assetGeneratedAt")).isAfter(at));safePositive(snapshot.path("assetSnapshotId"));uuid(snapshot,"valuationCaptureId");hash(snapshot,"inputSnapshotSha256");String inputRaw=text(snapshot,"inputBundleJcs");JsonNode input=SrppJcs.parseStrict(inputRaw);require(input.isObject()&&inputRaw.equals(SrppJcs.canonicalize(input))&&SrppJcs.sha256Hex(inputRaw).equals(snapshot.path("inputSnapshotSha256").asText()));
            require(input.path("ownerUserId").equals(identity.path("ownerUserId"))&&input.path("tradingDate").equals(identity.path("tradingDate"))&&input.path("slot").equals(identity.path("reportSlot"))&&input.path("authority").equals(revision));
            JsonNode state=input.path("stateBefore");require(state.isObject()&&state.path("ownerUserId").equals(identity.path("ownerUserId"))&&state.path("consumer").equals(identity.path("consumer"))&&state.path("tradingDate").equals(identity.path("tradingDate"))&&state.path("reportSlot").equals(identity.path("reportSlot"))&&Set.of("VERIFIED","UNAVAILABLE").contains(text(state,"status")));
            JsonNode sources=input.path("sources"),vector=snapshot.path("sourceVector");require(sources.isObject()&&vector.isObject()&&names(sources).equals(names(vector))&&sources.has("assets")&&sources.has("policy")&&sources.has("reservations")&&sources.has("core-state"));
            require(state.equals(sources.path("core-state")));JsonNode rawPolicy=sources.path("policy");require(SrppJcs.sha256Hex(text(rawPolicy,"rawModelBytes")).equals(revision.path("modelInputsSha256").asText())&&SrppJcs.sha256Hex(text(rawPolicy,"rawManifestBytes")).equals(revision.path("policyManifestSha256").asText()));
            vector.fields().forEachRemaining(e->{JsonNode v=e.getValue();keys(v,Set.of("sourceId","revision","capturedAt","sha256","coverage","validation"));require(e.getKey().equals(text(v,"sourceId"))&&!text(v,"revision").isBlank());hash(v,"sha256");require(!Instant.parse(text(v,"capturedAt")).isAfter(at)&&SrppJcs.hash(sources.path(e.getKey())).equals(v.path("sha256").asText())&&Set.of("COMPLETE","PARTIAL","NONE").contains(text(v,"coverage"))&&Set.of("VERIFIED","UNAVAILABLE").contains(text(v,"validation")));});
            JsonNode modules=n.path("modules");require(modules.isArray()&&modules.size()==12);Set<String> seen=new HashSet<>();Map<String,Integer> counts=new HashMap<>();
            for(JsonNode m:modules){keys(m,Set.of("moduleId","status","formulaVersion","scope","data","missing","reasonCodes","inputRefs","receipts"));String id=text(m,"moduleId"),status=text(m,"status");require(MODULES.contains(id)&&seen.add(id)&&Set.of("COMPLETE","PARTIAL","UNAVAILABLE","NOT_EVALUATED").contains(status)&&!text(m,"formulaVersion").isBlank()&&m.path("data").isObject()&&m.path("missing").isArray()&&m.path("reasonCodes").isArray()&&m.path("inputRefs").isArray()&&m.path("receipts").isArray());counts.merge(status,1,Integer::sum);references(m.path("inputRefs"),vector);require(m.path("scope").isArray());if("COMPLETE".equals(status)){require(m.path("missing").isEmpty());for(JsonNode ref:m.path("inputRefs"))require("VERIFIED".equals(vector.path(ref.asText()).path("validation").asText()));}keys(m.path("data"),Set.of("facts","legs","ranking","eventEvidenceIntegrationStatus"));require("NOT_BOUND".equals(m.path("data").path("eventEvidenceIntegrationStatus").asText()));validateFacts(m.path("data").path("facts"));walkRefs(m.path("receipts"),vector);walkRefs(m.path("data").path("legs"),vector);walkLegs(m.path("data"));}
            require(seen.equals(MODULES));JsonNode coverage=n.path("coverage");keys(coverage,Set.of("requestedCount","completeCount","partialCount","unavailableCount","notEvaluatedCount"));require(coverage.path("requestedCount").asInt(-1)==12);Map<String,String> fields=Map.of("COMPLETE","completeCount","PARTIAL","partialCount","UNAVAILABLE","unavailableCount","NOT_EVALUATED","notEvaluatedCount");fields.forEach((status,field)->require(coverage.path(field).isIntegralNumber()&&coverage.path(field).asInt(-1)==counts.getOrDefault(status,0)));
            safeJson(n);return n;
        } catch(RuntimeException invalid){if(invalid instanceof SrppReportProblem p)throw p;SrppReportProblem problem=new SrppReportProblem("UPSTREAM_INVALID");problem.initCause(invalid);throw problem;}
    }
    private static void references(JsonNode values,JsonNode vector){require(values.isArray());for(JsonNode v:values){require(v.isTextual());if(!vector.has(v.textValue()))throw new IllegalArgumentException("Missing report source reference: "+v.textValue());}}
    private static void validateFacts(JsonNode facts){require(facts.isArray());Set<String> identities=new HashSet<>();for(JsonNode fact:facts){keys(fact,Set.of("name","subject","value","unit","quality","reason"));require(!text(fact,"name").isBlank()&&!text(fact,"unit").isBlank()&&(fact.path("subject").isNull()||fact.path("subject").isTextual())&&identities.add(fact.path("name").asText()+"\u0000"+fact.path("subject").toString()));boolean unknown="UNAVAILABLE".equals(text(fact,"quality"));require(unknown==fact.path("value").isNull());if(unknown)require(fact.path("reason").isTextual());else require("EXACT".equals(fact.path("quality").asText())&&fact.path("value").isTextual()&&SrppDecimal.isCanonical(fact.path("value").asText()));}}
    private static void walkRefs(JsonNode n,JsonNode vector){if(n.isObject()){
        if(n.has("ruleId")){keys(n,Set.of("ruleId","calculatorVersion","inputRefs","status","reason","values","scope"));require(!text(n,"ruleId").isBlank()&&!text(n,"calculatorVersion").isBlank()&&n.path("reason").isTextual()&&Set.of("PASS","BLOCK","UNAVAILABLE","NOT_EVALUATED").contains(text(n,"status")));require("INTRADAY".equals(n.path("ruleId").asText())?"SHORT_ONLY".equals(n.path("scope").asText()):n.path("scope").isNull());validateFacts(n.path("values"));}
        n.fields().forEachRemaining(e->{if("inputRefs".equals(e.getKey()))references(e.getValue(),vector);else walkRefs(e.getValue(),vector);});
    }else if(n.isArray())n.forEach(v->walkRefs(v,vector));}
    private static void walkLegs(JsonNode n){if(n.isArray()){n.forEach(SrppReportEnvelopeValidator::walkLegs);return;}if(!n.isObject())return;
        if(n.has("strategy")&&n.has("symbol")&&n.has("status")){String status=text(n,"status");require(Set.of("ACTIONABLE_FOR_REPORT","BLOCKED","NOT_EVALUATED").contains(status));require(n.has("lots")||n.has("units"));for(String k:List.of("lots","units"))if(n.has(k)&&!n.path(k).isNull()){JsonNode qty=n.path(k);require(qty.isIntegralNumber()||qty.isTextual()&&SrppDecimal.isCanonical(qty.asText()));java.math.BigDecimal d=new java.math.BigDecimal(qty.asText());require(d.signum()>=0);if(!"ACTIONABLE_FOR_REPORT".equals(status))require(d.signum()==0);}
            for(String k:List.of("limitPrice","amount"))if(n.has(k)){if(!"ACTIONABLE_FOR_REPORT".equals(status))require(n.path(k).isNull());else require(n.path(k).isTextual()&&SrppDecimal.isCanonical(n.path(k).asText())&&new java.math.BigDecimal(n.path(k).asText()).signum()>0);}
        }n.forEach(SrppReportEnvelopeValidator::walkLegs);
    }
    private static void safeJson(JsonNode n){if(n.isFloatingPointNumber())throw new IllegalArgumentException();if(n.isIntegralNumber())require(n.canConvertToLong()&&n.longValue()>=-9007199254740991L&&n.longValue()<=9007199254740991L);if(n.isObject())n.fields().forEachRemaining(e->{require(!Set.of("password","accessToken","secretKey","internalToken","refreshToken").contains(e.getKey()));safeJson(e.getValue());});else if(n.isArray())n.forEach(SrppReportEnvelopeValidator::safeJson);}
    private static void safePositive(JsonNode n){require(n.isIntegralNumber()&&n.canConvertToLong()&&n.longValue()>0&&n.longValue()<=9007199254740991L);}
    private static String text(JsonNode n,String k){require(n.path(k).isTextual());return n.path(k).textValue();}
    private static void hash(JsonNode n,String k){require(text(n,k).matches("[a-f0-9]{64}"));}
    private static void uuid(JsonNode n,String k){require(text(n,k).matches("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}"));UUID.fromString(n.path(k).asText());}
    private static Set<String> names(JsonNode n){HashSet<String> names=new HashSet<>();n.fieldNames().forEachRemaining(names::add);return names;}
    private static void keys(JsonNode n,Set<String> expected){require(n.isObject()&&names(n).equals(expected));}
    private static void require(boolean condition){if(!condition)throw new IllegalArgumentException("Invalid report envelope");}
}
